from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
import os,json,time,random,secrets,threading
rooms={}; lock=threading.Lock()
HTML='<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>像素飞车 · 双人PK</title><style>*{box-sizing:border-box}body{margin:0;background:#101820;color:#eee;font:15px system-ui;text-align:center}main{max-width:460px;margin:auto;padding:12px}h2{margin:8px}button,input{padding:12px;border:0;border-radius:8px;font-size:16px;margin:4px}button{background:#d8ef78;color:#162019;font-weight:bold}input{width:130px}canvas{width:100%;height:auto;max-height:65dvh;object-fit:contain;background:#273039;touch-action:none;border-radius:12px}#hud{display:flex;justify-content:space-between;padding:8px}#msg{min-height:24px;color:#d8ef78}small{color:#aab5bc}html,body{height:100%;overflow:hidden}main{height:100vh;height:100dvh;display:flex;flex-direction:column;gap:4px;padding:8px 10px max(8px,env(safe-area-inset-bottom));max-width:480px}h2{font-size:19px;margin:2px}#menu{flex-shrink:0}#menu[hidden],#invite[hidden]{display:none}#msg{font-size:13px;min-height:18px}#hud{padding:4px}#track{flex:1;min-height:0;display:flex;justify-content:center;overflow:hidden}canvas{width:100%;height:100%;max-height:none;object-fit:fill}#controls{display:flex;gap:5px;flex-shrink:0}#controls button{flex:1;padding:12px 4px;margin:0}button{touch-action:manipulation}small{font-size:11px}#invite{font-size:12px;padding:6px;margin:0}body{background:radial-gradient(ellipse at top,#23394b,#090f19 65%)}button{background:#c9e979}#nitro{background:#70c9ff} </style><main><h2>像素飞车 / DUEL 0.2</h2><div id="menu"><button id="create">创建房间</button><input id="code" placeholder="6位房间号" inputmode="numeric" maxlength="6"><button id="join">加入</button><button id="solo">单人练习</button></div><div id="msg">邀请好友，挑战60秒</div><div id="hud"><span>🔵 你 <b id="mine">0</b></span><span id="clock">60s</span><span>🔴 好友 <b id="peer">0</b></span></div><button id="invite" hidden>复制邀请链接</button><div id="track"><canvas id="cv" width="320" height="480"></canvas></div><div id="controls"><button id="left">◀ 左移</button><button id="nitro">氮气 100%</button><button id="right">右移 ▶</button><button onclick="location.href=location.pathname">返回</button></div><small>滑动或点击车道 · 金币+10 · 护盾抵挡一次撞击 · 60秒决胜</small></main><script>\nconst $=id=>document.getElementById(id),c=$(\'cv\'),g=c.getContext(\'2d\');let room=null,seed=123,start=0,offset=0,lane=1,score=0,dead=false,other=null,active=false,solo=false,last=0,hits=new Set(),busy=false,ended=false,shield=1,nitro=100,boostUntil=0,bonus=0,crashes=new Set(),lastRun=0,netOK=true;const msg=s=>$(\'msg\').textContent=s;\nasync function api(path,d){let r=await fetch(\'/\'+path,{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(d)});let j=await r.json();if(!r.ok)throw Error(j.error);return j}\nasync function enter(path){try{room=await api(path,{code:$(\'code\').value.trim()});$(\'menu\').hidden=true;$(\'invite\').hidden=false;msg(\'房间 \'+room.code+\' · 发给好友\');sync()}catch(e){msg(\'连接失败：请确认服务器已启动、房间号正确\')}}\n$(\'invite\').onclick=async()=>{let u=new URL(location.href);u.searchParams.set(\'room\',room.code);try{await navigator.clipboard.writeText(u.href);msg(\'邀请链接已复制\')}catch(e){prompt(\'长按复制邀请链接\',u.href)}};let invited=new URLSearchParams(location.search).get(\'room\');if(/^\\d{6}$/.test(invited||\'\'))$(\'code\').value=invited; $(\'nitro\').onclick=()=>{if(active&&!dead&&Date.now()/1000+offset>=start&&nitro>=40){nitro-=40;boostUntil=Date.now()/1000+2}}; $(\'create\').onclick=()=>enter(\'create\');$(\'join\').onclick=()=>enter(\'join\');$(\'solo\').onclick=()=>{solo=true;active=true;start=Date.now()/1000+3;seed=Date.now()|0;$(\'menu\').hidden=true};\nasync function sync(){if(!room||busy)return;busy=true;try{let r=await api(\'sync\',{...room,score,dead,x:lane});netOK=true;offset=r.now-Date.now()/1000;seed=r.seed;start=r.start;other=r.other;active=!!start;if(!start)msg(\'房间 \'+room.code+\' · 等待好友\');$(\'peer\').textContent=other?other.score:0;if(ended&&other&&other.dead)result()}catch(e){netOK=false;msg(\'网络连接中断，正在重试\')}finally{busy=false}}\nsetInterval(sync,350);function result(){if(solo)msg(\'练习结束 · \'+score+\' 分\');else if(other&&other.dead)msg(score===other.score?\'平局！\':score>other.score?\'你赢了！\':\'好友获胜！\');else msg(\'本局结束，等待好友完成\')}\nfunction move(n){if(!dead)lane=Math.max(0,Math.min(2,n))}$(\'left\').onclick=()=>move(lane-1);$(\'right\').onclick=()=>move(lane+1);function touch(e){let r=c.getBoundingClientRect();move(Math.floor((e.clientX-r.left)/r.width*3))}c.onpointerdown=e=>{c.setPointerCapture(e.pointerId);touch(e)};c.onpointermove=e=>{if(e.buttons)touch(e)};\nfunction rand(i){let n=Math.imul(i+seed,1664525)+1013904223;n=Math.imul(n^(n>>>16),2246822519);return (n>>>0)/4294967296}function car(x,y,col){g.fillStyle=\'#12171a\';for(let a of [-19,13])for(let b of [-20,10])g.fillRect(x+a,y+b,6,12);g.fillStyle=col;g.fillRect(x-13,y-25,26,50);g.fillStyle=\'#9ebcc9\';g.fillRect(x-9,y-14,18,11);g.fillRect(x-9,y+10,18,6);g.fillStyle=\'#fff2bd\';g.fillRect(x-10,y-23,6,4);g.fillRect(x+4,y-23,6,4);g.fillStyle=\'#ff645b\';g.fillRect(x-10,y+20,6,4);g.fillRect(x+4,y+20,6,4)}\nfunction frame(){let t=active?Date.now()/1000+offset-start:0;let run=Math.max(0,Math.min(60,t));let travel=run*145;let boosting=Date.now()/1000<boostUntil;let dt=Math.max(0,Math.min(.1,run-lastRun));lastRun=run;if(active&&!dead&&t>=0){nitro=Math.min(100,nitro+dt*4);if(boosting)bonus+=dt*8;}$(\'nitro\').textContent=\'氮气 \'+Math.floor(nitro)+\'%\';g.fillStyle=\'#26323a\';g.fillRect(0,0,320,480);g.fillStyle=\'#526b50\';g.fillRect(0,0,12,480);g.fillRect(308,0,12,480);for(let yy=-35+travel%65;yy<480;yy+=65){for(let xx of [5,315]){g.fillStyle=\'#2d493c\';g.fillRect(xx-4,yy,8,19);g.fillStyle=\'#83a86c\';g.fillRect(xx-6,yy,12,12)}}g.fillStyle=\'#b6c2bd\';for(let x of [106,213])for(let y=-40+travel%50;y<480;y+=50)g.fillRect(x,y,2,23);let xpos=53+lane*107;\nfor(let i=Math.max(0,Math.floor((travel-550)/145));i<Math.floor(travel/145)+3;i++){let y=travel-i*145-70, l=Math.floor(rand(i)*3),x=53+l*107;let coinLane=(l+1+Math.floor(rand(i+900)*2))%3,cx=53+coinLane*107;car(x,y,\'#78828c\');if(!hits.has(\'c\'+i)){g.fillStyle=\'#f6c758\';g.beginPath();g.arc(cx,y,8,0,7);g.fill();g.fillStyle=\'#a67924\';g.fillRect(cx-1,y-4,2,8)}if(active&&t>=0&&!dead&&Math.abs(y-400)<32){if(l===lane&&!crashes.has(i)){crashes.add(i);if(shield){shield=0;if(navigator.vibrate)navigator.vibrate(90)}else{dead=true;ended=true;if(navigator.vibrate)navigator.vibrate(200);result()}}else if(coinLane===lane&&!hits.has(\'c\'+i)){hits.add(\'c\'+i);score+=10}}}\nif(active&&t>=0&&!dead){score=Math.max(score,Math.floor(run*5+bonus)+hits.size*10);if(t>=60){dead=true;ended=true;result()}else if(netOK)msg((shield?\'护盾就绪\':\'护盾已消耗\')+(boosting?\' · 氮气积分加成\':\' · 比赛进行中\'))}else if(active&&t<0)msg(\'准备 \'+Math.ceil(-t)+\' 秒\');if(boosting&&!dead){g.fillStyle=\'#75dcff\';g.fillRect(xpos-6,425,12,8+Math.random()*13)}car(xpos,400,\'#53a9ef\');if(shield&&!dead){g.strokeStyle=\'#77d9ff\';g.lineWidth=2;g.strokeRect(xpos-22,370,44,60)}if(other&&!other.dead){g.globalAlpha=.35;car(53+other.x*107,400,\'#ff665e\');g.globalAlpha=1}$(\'mine\').textContent=score;$(\'clock\').textContent=Math.ceil(60-run)+\'s\';requestAnimationFrame(frame)}frame();\n</script></html>\n' .encode("utf-8")

class Handler(BaseHTTPRequestHandler):
 def send(self,data,status=200,kind='application/json'):
  if not isinstance(data,bytes): data=json.dumps(data).encode()
  self.send_response(status); self.send_header('Content-Type',kind); self.send_header('Cache-Control','no-store'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
 def do_GET(self):
  if self.path.split('?')[0]=='/': self.send(HTML,kind='text/html; charset=utf-8')
  else: self.send({},404)
 def do_POST(self):
  try:
   n=int(self.headers.get('Content-Length',0)); assert 0<n<4096; d=json.loads(self.rfile.read(n)); now=time.time()
   with lock:
    for k in list(rooms):
     if now-rooms[k]['seen']>1800: del rooms[k]
    if self.path=='/create':
     if len(rooms)>=300: raise ValueError('Room limit')
     code=str(random.randint(100000,999999))
     while code in rooms: code=str(random.randint(100000,999999))
     r=rooms[code]={'seen':now,'seed':random.randrange(1,2**31),'start':0,'players':{}}; token=secrets.token_hex(16); r['players'][token]={'score':0,'dead':False,'x':1}; result={'code':code,'token':token}
    elif self.path=='/join':
     code=str(d['code']); r=rooms[code]; r['seen']=now; assert len(r['players'])==1 and not r['start'],'Room full'; token=secrets.token_hex(16); r['players'][token]={'score':0,'dead':False,'x':1}; r['start']=now+4; result={'code':code,'token':token}
    elif self.path=='/sync':
     r=rooms[str(d['code'])]; token=d['token']; p=r['players'][token]; r['seen']=now
     if r['start'] and now>=r['start']:
      if not p['dead']: p.update(score=max(p['score'],min(2000,int(d['score']))),dead=bool(d['dead']),x=max(0,min(2,int(d['x']))))
     result={'seed':r['seed'],'start':r['start'],'now':now,'other':next((v for k,v in r['players'].items() if k!=token),None)}
    else: raise ValueError('Unknown endpoint')
   self.send(result)
  except Exception as e: self.send({'error':'Room unavailable or invalid request'},400)
if __name__=='__main__':
 port=int(os.environ.get('PORT','8080')); host='0.0.0.0' if 'PORT' in os.environ else '127.0.0.1'
 print(f'Listening on {host}:{port}',flush=True); ThreadingHTTPServer((host,port),Handler).serve_forever()
